INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betoekner forkortelsen MAIN som beskriver aarsagerne til Forste Verdenskrig?","options":["Militarisme, Alliancer, Imperialisme og Nationalisme","Moerke, Angreb, Invasion og Neutralitet","Magt, Agression, Interesser og Naboer","Mobilisering, Anneksion, Information og Normer"],"correct":"Militarisme, Alliancer, Imperialisme og Nationalisme","accepted_answers":["Militarisme, Alliancer, Imperialisme og Nationalisme"],"review_text":"Historikere bruger MAIN som huskeregel. Militarisme: rustningskaapplobet. Alliancer: automatiske forpligtelser. Imperialisme: kolonirivalisering. Nationalisme: stolthed og fjendskab. Ingen enkelt aarsag men alle fire samlet."}'::jsonb,
  'mc','short','{"concepts":["MAIN","militarisme","alliancer","imperialisme","nationalisme"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvilke lande udgoerde Triple Entente og Triple Alliance foer Forste Verdenskrig?","options":["Triple Entente: Frankrig, Rusland og England. Triple Alliance: Germany, Oestrig-Ungarn og Italien","Triple Entente: Germany, Oestrig-Ungarn og Tyrkiet. Triple Alliance: Frankrig, Rusland og England","Begge alliancer bestod af de samme fem lande","Triple Entente: USA, England og Frankrig. Triple Alliance: Germany og Oestrig"],"correct":"Triple Entente: Frankrig, Rusland og England. Triple Alliance: Germany, Oestrig-Ungarn og Italien","accepted_answers":["Triple Entente: Frankrig, Rusland og England. Triple Alliance: Germany, Oestrig-Ungarn og Italien"],"review_text":"Europa var delt i to lejer. Triple Entente vandt. Men ved krigens start skiftede Italien side og England og Frankrig fik USA med i 1917. Alliancerne var ikke faste men de skabte automatiske forpligtelser."}'::jsonb,
  'mc','short','{"concepts":["Triple Entente","Triple Alliance","alliancer","krigsdeltagere"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvornaar og hvor udkaempedes Forste Verdenskrig?","options":["1914-1918 primaert i Europa men ogsaa i Mellemøesten, Afrika og Asien","1910-1918 kun i Europa","1914-1920 kun paa Vestfronten","1916-1918 primaert i Rusland og Tyrkiet"],"correct":"1914-1918 primaert i Europa men ogsaa i Mellemøesten, Afrika og Asien","accepted_answers":["1914-1918 primaert i Europa men ogsaa i Mellemøesten, Afrika og Asien"],"review_text":"Krigen varede fra august 1914 til november 1918. Vestfronten i Frankrig og Belgien var den mest beromte. Men der var ogsaa Oestfronten mod Rusland, krig i Mellemoeesten og soeslag i Atlanterhavet."}'::jsonb,
  'mc','short','{"concepts":["krig 1914-1918","fronter","Vestfronten","global konflikt"],"misconception_type":"scope_confusion","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad indeholdt Versailles-traktaten fra 1919?","options":["Germany fik skylden for krigen, maatte betale store erstatninger og afgive territorier","Alle lande fik ens betingelser og delte krigsomkostningerne ligeligt","Traktaten garanterede Germany beskyttelse mod fremtidige angreb","Traktaten skabte et forenet Europa med faelles graenser"],"correct":"Germany fik skylden for krigen, maatte betale store erstatninger og afgive territorier","accepted_answers":["Germany fik skylden for krigen, maatte betale store erstatninger og afgive territorier"],"review_text":"Paragraf 231 var krigsscyldsklausulen. Germany fik skylden for hele krigen. Det skulle betale massive erstatninger og afstaa territorier herunder Alsace-Lorraine. Germany mistede ogsaa sine kolonier og store dele af sin haer."}'::jsonb,
  'mc','short','{"concepts":["Versailles","krigsscyldsklausul","erstatninger","territorier","1919"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvilke nye vaabentyper blev indfoert i Forste Verdenskrig?","options":["Tanks, fly, undervandsbaade og kemiske vaaaben som giftgas","Nukleare bomber og ballistiske missiler","Lasservaaben og droner","Maskingevaeret var den eneste nye teknologi"],"correct":"Tanks, fly, undervandsbaade og kemiske vaaaben som giftgas","accepted_answers":["Tanks, fly, undervandsbaade og kemiske vaaaben som giftgas"],"review_text":"Tanks broede igennem skyttegravslinjer. Fly patruljerede og bombede. Undervandsbaade angreb forsyningsskibe. Giftgas var den mest frygtede nyhed. Alle disse teknologier var nye og aendrede krigsforlobet."}'::jsonb,
  'mc','short','{"concepts":["tanks","fly","undervandsbaade","giftgas","ny teknologi"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betod begrebet total krig under Forste Verdenskrig?","options":["At hele samfundet var mobiliseret til krig herunder fabrikker, kvinder, okonomi og propaganda","At krigen foregik 24 timer i dognet uden pauser","At alle militaere ressourcer blev brugt paa een gang","At krigen spredte sig til alle verdensdele"],"correct":"At hele samfundet var mobiliseret til krig herunder fabrikker, kvinder, okonomi og propaganda","accepted_answers":["At hele samfundet var mobiliseret til krig herunder fabrikker, kvinder, okonomi og propaganda"],"review_text":"Total krig betod at skellet mellem civil og militaer sloev. Fabrikker producerede vaaaben. Kvinder arbejdede i industrien. Okonomier blev omstillet til krigsproduktion. Staten kontrollerede madvarer og information."}'::jsonb,
  'mc','short','{"concepts":["total krig","mobilisering","hjemmefront","stat","civil-militaer"],"misconception_type":"scope_confusion","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',8,1
);

