INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Var Forste Verdenskrig uundgaaelig?","options":["Det debatteres stadig. Strukturelle spaendinger var enorme men konkrete politiske beslutninger i juli 1914 kunne have stoppet krigen","Ja krigen var fuldstaendig uundgaaelig givet de strukturelle betingelser","Nej krigen var et tilfaeldigt uheld som nemt kunne vaere undgaaet","Krigen var uundgaaelig fordi Germany planlagde den systematisk i aartier"],"correct":"Det debatteres stadig. Strukturelle spaendinger var enorme men konkrete politiske beslutninger i juli 1914 kunne have stoppet krigen","accepted_answers":["Det debatteres stadig. Strukturelle spaendinger var enorme men konkrete politiske beslutninger i juli 1914 kunne have stoppet krigen"],"review_text":"Strukturalisterne siger spaendingerne var saa store at noget maatte eksplodere. Andre peeger paa at lederne i de afgoorende julidage 1914 aktivt valgte eskalering frem for kompromis. Sandsynligvis bidrog begge: strukturerne skaabte betingelserne men mennesker traf beslutningerne."}'::jsonb,
  'mc','short','{"concepts":["uundgaaelighed","strukturer","beslutninger","julidagene","historisk debat"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',4,'auto',true,'world_war_1',8,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Var Versailles-traktaten en retfaerdig fred eller en opskrift paa ny krig?","options":["Begge dele paa en gang: forstaaeelig fra sejrherrernes perspektiv men saa haard at den saaede froe til den naeste krig","Den var fuldt retfaerdig og ingen historiker kritiserer den","Den var katastrofalt uretfaerdig og ingen vidste bedre","Den var saa mild at det var grunden til at Hitler kom til magten"],"correct":"Begge dele paa en gang: forstaaeelig fra sejrherrernes perspektiv men saa haard at den saaede froe til den naeste krig","accepted_answers":["Begge dele paa en gang: forstaaeelig fra sejrherrernes perspektiv men saa haard at den saaede froe til den naeste krig"],"review_text":"Fra fransk perspektiv var haardhed forstaaeelig: Frankrig var haerget. Men okonomisten Keynes forudsagde i 1919 at traktatens betingelser ville skabe en ny krig inden 20 aar. Han fik desvaerre ret i 1939."}'::jsonb,
  'mc','short','{"concepts":["Versailles","retfaerdig fred","Keynes","konsekvenser","perspektiver"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',4,'auto',true,'world_war_1',8,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad viser brugen af propaganda i England, Frankrig og USA om forholdet mellem demokrati og statsstyret manipulation?","options":["At demokratier er villige til at manipulere borgerne i eksistentielle kriser og at medierne aktivt samarbejdede med staten","At demokratier aldrig bruger propaganda det goer kun diktaturer","At demokratiernes propaganda var fuldt etisk modsat diktaturers","At borgerne gennemskuede al propaganda og den var ineffektiv"],"correct":"At demokratier er villige til at manipulere borgerne i eksistentielle kriser og at medierne aktivt samarbejdede med staten","accepted_answers":["At demokratier er villige til at manipulere borgerne i eksistentielle kriser og at medierne aktivt samarbejdede med staten"],"review_text":"England oprettede et dedikeret Propagandaministerium. USA brugte Committee on Public Information. Aviser og film formidlede krigens noedvendighed. Borgerne i disse demokratier var udsat for statsstyret informationskrig der var meget effektiv."}'::jsonb,
  'mc','short','{"concepts":["propaganda","demokrati","statsstyret","manipulation","misconception-propaganda-kun-diktaturer"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',4,'auto',true,'world_war_1',8,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad fortaeller kloeften mellem krigstidens propaganda og soldaternes egne dagboeger om information og magt?","options":["At dem der styrer informationen kan forme virkelighed for store befolkningsgrupper og at censur aktivt holdt sandheden fra offentligheden","At soldaterne faktisk var enige med propagandaen","At propaganda aldrig virker fordi folk gennemskuer det","At informationskontrol kun var mulig foer aviser eksisterede"],"correct":"At dem der styrer informationen kan forme virkelighed for store befolkningsgrupper og at censur aktivt holdt sandheden fra offentligheden","accepted_answers":["At dem der styrer informationen kan forme virkelighed for store befolkningsgrupper og at censur aktivt holdt sandheden fra offentligheden"],"review_text":"Mens propaganda fremstillede heroisk krig levede soldaterne i mudder og gas. Breve hjem var censurerede. Det er et tidligt og magtfuldt eksempel paa at kontrol over information er kontrol over virkelighed."}'::jsonb,
  'mc','short','{"concepts":["informationskontrol","censur","magt","virkelighed","dagboeger"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',4,'auto',true,'world_war_1',8,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er Forste Verdenskrigs vigtigste arv til verden i dag?","options":["At verdenskrig er mulig og at nationalisme, rivalisering og svage internationale institutioner kan bringe civilisationer til ruinens rand","At teknologisk overlegenhed altid afgoer en krig","At demokratier aldrig goer krig mod hinanden","At Europas dominans over verden er permanent og urokkeaelig"],"correct":"At verdenskrig er mulig og at nationalisme, rivalisering og svage internationale institutioner kan bringe civilisationer til ruinens rand","accepted_answers":["At verdenskrig er mulig og at nationalisme, rivalisering og svage internationale institutioner kan bringe civilisationer til ruinens rand"],"review_text":"Forste Verdenskrig draebte 20 millioner. Den udraderede fire imperier. Den saaede froe til den naeste krig. Dens lektie: den internationale orden er skroebelig og krig er aldrig det korte sejrstogt man lover. Det var baggrunden for FN og det europaeiske integrationsprojekt."}'::jsonb,
  'mc','short','{"concepts":["arv","FN","europaeisk integration","lektie","international orden"],"misconception_type":"temporal_confusion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',4,'auto',true,'world_war_1',8,4
);;
